# repository.py
cat << 'EOF' > src/uuid_service/repository.py
from dataclasses import dataclass

import boto3
from botocore.exceptions import ClientError

from .config import get_config
from .logging_utils import get_logger

logger = get_logger(__name__)


class UUIDStoreError(Exception):
    """Raised when the service cannot store a UUID in DynamoDB."""


@dataclass
class _RepositoryContext:
    table_name: str


_config = get_config()
_ctx = _RepositoryContext(table_name=_config.table_name)
_dynamodb = boto3.resource("dynamodb", region_name=_config.region_name)
_table = _dynamodb.Table(_ctx.table_name)


def store_uuid(uuid_value: str) -> None:
    """Store a UUID in DynamoDB, enforcing uniqueness via a conditional write."""
    try:
        _table.put_item(
            Item={"uuid": uuid_value},
            ConditionExpression="attribute_not_exists(#u)",
            ExpressionAttributeNames={"#u": "uuid"},
        )
    except ClientError as exc:
        logger.exception("Error storing UUID", extra={"uuid": uuid_value})
        raise UUIDStoreError(str(exc)) from exc
EOF

# handler.py
cat << 'EOF' > src/uuid_service/handler.py
import json
from typing import Any, Dict

from .logging_utils import get_logger
from .uuid_generator import generate_uuid
from .repository import UUIDStoreError, store_uuid

logger = get_logger(__name__)


def handler(event: Dict[str, Any], context: Any) -> Dict[str, Any]:
    """AWS Lambda handler for API Gateway HTTP API events.

    Generates a UUID, stores it in DynamoDB, and returns it as JSON.
    """
    logger.info("Received event", extra={"event": event})

    uuid_value = generate_uuid()

    try:
        store_uuid(uuid_value)
    except UUIDStoreError:
        logger.exception("Failed to store UUID", extra={"uuid": uuid_value})
        return {
            "statusCode": 500,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"message": "Failed to store UUID"}),
        }

    response_body = {"uuid": uuid_value}
    return {
        "statusCode": 200,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(response_body),
    }
EOF

